<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useQuasar, useMeta } from 'quasar'
import { io } from 'socket.io-client'
import { api, apiBaseURL } from 'boot/axios'
import AuthDialog from 'components/AuthDialog.vue'
import IAChatComponent from 'components/IAChatComponent.vue'
import SolutionMediaFrame from 'components/SolutionMediaFrame.vue'
import KitTeamSection from 'components/KitTeamSection.vue'
import LandingVideoMonitor from 'components/landing3d/LandingVideoMonitor.vue'
import { solutionsMedia, solutionDemos } from 'src/data/whatsappSolutionsMedia'
import { botBuilderHeroVideo } from 'src/data/landingHeroVideo'
const router = useRouter(), route = useRoute(), $q = useQuasar()
useMeta({ title: 'Kit AitoNotify + WhatsApp BotBuilder | AitoSoftwares', meta: { description: { name: 'description', content: 'Campanhas, notificações e atendimento com BotBuilder, IA e equipe no mesmo AitoNotify + WhatsApp BotBuilder. Código-fonte com licença ou plano mensal.' } }, link: { canonical: { rel: 'canonical', href: 'https://aitosoftwares.com/whatsapp-solucoes' } } })
const assistantOpen = ref(false)
const productPage = ref(null)
let revealObserver
onMounted(() => {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches || !('IntersectionObserver' in window)) return
  const root = productPage.value?.$el
  revealObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return
      entry.target.classList.add('is-revealed')
      revealObserver.unobserve(entry.target)
    })
  }, { threshold: 0.06, rootMargin: '0px 0px -30px 0px' })
  root?.querySelectorAll('section').forEach(section => {
    if (section.getBoundingClientRect().top < window.innerHeight - 30) return
    section.classList.add('product-reveal')
    revealObserver.observe(section)
  })
})
onBeforeUnmount(() => revealObserver?.disconnect())
const loginOpen = ref(false), confirming = ref(false), paymentMessage = ref(''), buying = ref(false), checkoutOpen = ref(false), order = ref(null), purchased = ref(false)
const offer = ref({ available: false, priceCents: null, originalPriceCents: null, monthlyEnabled: false, monthlyPriceCents: null, monthlyTitle: 'AitoNotify + WhatsApp BotBuilder mensal', monthlyDescription: '', media: {} })
const activeSlide = ref('cloud')
const monthlyUrl = computed(() => { try { const url = new URL(offer.value.monthlyUrl); if (url.protocol === 'https:' && url.hostname === 'wa.me' && /^\/\d{10,15}$/.test(url.pathname)) return url.href } catch {} return 'https://wa.me/5561982637865?text=' + encodeURIComponent('Quero conhecer o AitoNotify + WhatsApp BotBuilder no plano mensal.') })
const productVideo = computed(() => ({ src: offer.value.media?.heroVideo || botBuilderHeroVideo.src, poster: offer.value.media?.heroPoster || botBuilderHeroVideo.poster }))
const demos = solutionDemos
const prototypeUrl = 'https://notify-flow.onrender.com/prototype'
function scrollToProductSection(event) {
  const anchor = event.target.closest?.('a[href^="#"]')
  const target = anchor && document.getElementById(anchor.getAttribute('href').slice(1))
  if (!target) return
  event.preventDefault()
  target.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' })
  window.history.replaceState(window.history.state, '', anchor.getAttribute('href'))
}


const checkoutReturn = computed(() => typeof route.query.order_nsu === 'string' && typeof route.query.transaction_nsu === 'string' && typeof (route.query.slug || route.query.invoice_slug) === 'string')
const authReturnPath = computed(() => checkoutReturn.value ? route.fullPath : '/whatsapp-solucoes?comprar=1')
const money = cents => cents == null ? 'Consulte disponibilidade' : (Number(cents) / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
const headers = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('aito_user_token') || ''}` } })
let socket, timer
function connect() {
  if (socket || !localStorage.getItem('aito_user_token')) return
  const url = new URL(apiBaseURL, window.location.origin)
  socket = io(`${url.origin}/products`, { auth: { token: localStorage.getItem('aito_user_token') }, transports: ['websocket', 'polling'], reconnectionDelay: 1500 })
  socket.on('purchase.updated', event => { if (!order.value || order.value.orderNsu === event.orderNsu) refreshPurchase() })
  socket.on('connect', () => { if (checkoutOpen.value) refreshPurchase() })
}
async function refreshPurchase() {
  if (!localStorage.getItem('aito_user_token')) return
  try { const data = (await api.get('/products/aitonotify', headers())).data.data; purchased.value = data.licenses.some(item => item.active); if (order.value) order.value = data.orders.find(item => item.orderNsu === order.value.orderNsu) || order.value } catch { /* o próximo evento ou consulta reconcilia a confirmação */ }
}
async function buy() {
  if (buying.value) return
  if (!localStorage.getItem('aito_user_token')) { loginOpen.value = true; return }
  checkoutOpen.value = true; buying.value = true; paymentMessage.value = ''; connect()
  clearInterval(timer); timer = setInterval(() => { if (checkoutOpen.value) refreshPurchase() }, 15000)
  try {
    await refreshPurchase()
    if (!purchased.value) order.value = (await api.post('/products/aitonotify/checkout', {}, headers())).data.data
  } catch (error) { paymentMessage.value = error.response?.data?.message || 'Não foi possível abrir o checkout. Tente novamente.' }
  finally { buying.value = false }
}
async function confirmCheckout() {
  if (!checkoutReturn.value || confirming.value) return
  if (!localStorage.getItem('aito_user_token')) { loginOpen.value = true; paymentMessage.value = 'Entre com a conta usada na compra para confirmar o pagamento.'; return }
  checkoutOpen.value = true; confirming.value = true; paymentMessage.value = ''; connect()
  try {
    await api.post('/products/aitonotify/confirm', { order_nsu: route.query.order_nsu, transaction_nsu: route.query.transaction_nsu, slug: route.query.slug || route.query.invoice_slug }, headers())
    await refreshPurchase()
    $q.notify({ type: 'positive', message: 'Pagamento confirmado. Seu código e token estão em Meus produtos.' })
  } catch (error) { paymentMessage.value = error.response?.data?.message || 'Pagamento aguardando confirmação. Consulte novamente em instantes.' }
  finally { confirming.value = false }
}
function onAuthenticated() { connect(); if (checkoutReturn.value) confirmCheckout(); else buy() }
onMounted(async () => { try { offer.value = (await api.get('/products/aitonotify/public')).data.data } catch { paymentMessage.value = 'Oferta indisponível no momento.' } connect(); if (checkoutReturn.value) confirmCheckout(); else if (route.query.comprar === '1') buy() })
onBeforeUnmount(() => { socket?.disconnect(); clearInterval(timer) })
</script>
<template>
<q-layout view="hHh lpR fFf"><q-page-container><q-page ref="productPage" class="product solutions-product" @click="scrollToProductSection">
<a class="floating-prototype" :href="prototypeUrl" target="_blank" rel="noopener noreferrer"><q-icon name="mdi-play-circle"/> Testar demonstração</a>
<header class="solutions-navbar"><router-link to="/" class="brand solutions-brand"><img src="/aito-logo-restored.png" alt="" width="34" height="34"/><span>AITO<span>SOFTWARES</span></span></router-link><nav aria-label="Navegação do produto"><a href="#pacote">O kit</a><a href="#equipe">Sua equipe</a><a href="#demonstracao">Por dentro</a><a href="#planos">Planos</a><a class="nav-trial" :href="prototypeUrl" target="_blank" rel="noopener noreferrer">Experimentar grátis <q-icon name="mdi-arrow-top-right"/></a></nav></header>
<main class="hero solutions-hero"><div class="copy"><span class="kit-label">AITONOTIFY + WHATSAPP BOTBUILDER</span><span class="eyebrow">NOTIFIQUE. CONVERSE. AUTOMATIZE.</span><h1>Automatize o atendimento.<br/><em>Escale suas notificações.</em></h1><p>Chatbots com IA e disparos pela API oficial. Sua equipe, seus canais e sua marca no <strong>AitoNotify + WhatsApp BotBuilder.</strong></p><div class="hero-actions"><a class="trial-cta" href="#chatbots" data-funnel="interest_chatbots"><q-icon name="mdi-robot-outline"/><span>Quero chatbots e IA</span></a><a class="trial-cta notifications-cta" href="#notificacoes" data-funnel="interest_notifications"><q-icon name="mdi-bullhorn-outline"/><span>Quero notificações em massa<small>Pela API oficial da Meta</small></span></a></div><div class="trust"><q-icon name="mdi-monitor-eye"/> Conheça a experiência antes de escolher seu plano.</div><div class="highlights"><span>API oficial + BotBuilder</span><span>Equipe com login individual</span><span>Sua marca no painel</span></div></div><div class="hero-video"><LandingVideoMonitor :video="productVideo" title="Conheça o AitoNotify + WhatsApp BotBuilder" eyebrow="VEJA A OPERAÇÃO ACONTECER" headline="Da primeira mensagem ao próximo passo." description="Notificações, atendimento e automação em um só ecossistema."/></div></main>
<section id="pacote" class="solution-package"><div class="section-heading"><span class="eyebrow">UM KIT. CANAIS CONECTADOS. PAPÉIS BEM DEFINIDOS.</span><h2>A mensagem chega.<br/><em>Sua operação continua.</em></h2><p>Prepare campanhas, acompanhe entregas e transforme as respostas em atendimento. AitoNotify e WhatsApp BotBuilder fazem parte do mesmo pacote, com contatos compartilhados e conexões gerenciadas separadamente.</p></div><div class="solution-pair"><article id="notificacoes"><span class="solution-number">01 / NOTIFICAÇÕES MULTICANAL</span><q-icon name="mdi-cloud-check-outline" size="42px"/><h3>Alcance com organização.</h3><p>Envie avisos, atualizações e campanhas para contatos autorizados pelo WhatsApp Cloud API, Telegram e Gmail. Revise o conteúdo, programe os envios e acompanhe o resultado por canal.</p><ul><li>API oficial da Meta e templates com variáveis.</li><li>Grupos de contatos, convites e consentimento.</li><li>Filas, agendamentos e recorrências.</li><li>Status e tentativas por contato e canal.</li></ul><small>Os envios pela Cloud API seguem os modelos, a qualidade e os limites da conta Meta.</small></article><article id="chatbots"><span class="solution-number">02 / WHATSAPP WEB + BOTBUILDER</span><q-icon name="mdi-sitemap-outline" size="42px"/><h3>Atendimento com continuidade.</h3><p>Conecte uma sessão por QR Code, desenhe o fluxo e deixe o bot organizar a chegada do cliente. A IA apoia a conversa e sua equipe assume com o histórico no mesmo painel.</p><ul><li>Editor visual, simulador e importação de fluxos.</li><li>Triagem, responsáveis e assinaturas opcionais.</li><li>Catálogo, pedidos, arquivos e ações integradas.</li><li>Uma sessão no servidor, vários acessos da equipe.</li></ul><small>A sessão WhatsApp Web é uma modalidade não oficial, independente do número conectado à Cloud API.</small></article></div><div class="operations-overview"><SolutionMediaFrame :src="offer.media?.overview || solutionsMedia.overview" title="Central de canais e configurações"/><p>WhatsApp Cloud, Telegram e Gmail, alertas de mensagens, proteção por e-mail e configurações da operação em um painel com sua identidade.</p></div></section>
<KitTeamSection :image="offer.media?.teamAccess || solutionsMedia.web"/>
<section class="builder-preview"><div class="builder-preview__copy"><span class="eyebrow">MENOS CADASTRO REPETITIVO. MAIS TEMPO PARA ATENDER.</span><h2>Do print da Meta ao template.<br/>Com a Aito I.A.</h2><p>Você já criou um modelo na Meta. Em vez de copiar cada campo, envie os prints para a assistente: ela interpreta texto, idioma, botões e variáveis e prepara o cadastro para sua revisão.</p><ul class="feature-list"><li>Crie e adapte fluxogramas em linguagem natural.</li><li>Prepare campanhas, templates, sites e e-mails.</li><li>Veja as ações propostas e confirme antes da execução.</li><li>Escolha os modelos disponíveis na sua conta OpenAI.</li></ul><p class="text-caption">Usa sua chave e créditos OpenAI. Os prints precisam de revisão; o cadastro no sistema não substitui a aprovação da Meta.</p></div><div class="hero-devices"><SolutionMediaFrame :src="offer.media?.botFlow" title="Editor visual de fluxos" demo="flow" suggestion="Mostre um fluxo com triagem, IA e atendimento humano."/></div></section><section id="demonstracao" class="solution-demonstration"><div class="section-heading"><span class="eyebrow">VEJA O PRODUTO POR DENTRO</span><h2>Do conteúdo ao atendimento.<br/><em>Cada etapa à vista.</em></h2><p>Explore as telas de campanhas, templates, entregas e conversas. Toque na moldura para ampliar os detalhes.</p></div><q-carousel v-model="activeSlide" animated swipeable arrows infinite class="solutions-carousel" control-color="teal-3"><q-carousel-slide v-for="demo in demos" :key="demo.key" :name="demo.key" class="solution-slide"><div class="slide-copy"><span class="eyebrow">{{ String(demos.indexOf(demo) + 1).padStart(2, '0') }} / POR DENTRO DO AITONOTIFY</span><h3>{{ demo.title }}</h3><p>{{ demo.copy }}</p></div><SolutionMediaFrame :src="offer.media?.[demo.media] || demo.image" :title="demo.title"/></q-carousel-slide></q-carousel><div class="demo-tabs" role="group" aria-label="Escolher captura do produto"><button v-for="demo in demos" :key="demo.key" type="button" :aria-pressed="activeSlide === demo.key" :aria-label="`Ver captura: ${demo.title}`" @click="activeSlide = demo.key">{{ demo.tab }}</button></div><p class="demo-note">Capturas de demonstração com dados pessoais e identificadores ocultados quando necessário.</p></section>
<section class="solution-mobile"><div><span class="eyebrow">UMA OPERAÇÃO QUE ACOMPANHA VOCÊ.</span><h2>Seu atendimento<br/><em>também cabe no bolso.</em></h2><p>Abra o painel pelo celular, escolha o canal e encontre a conversa certa. Adicione o webapp à tela inicial e ative os alertas de novas mensagens nos dispositivos compatíveis.</p><ul class="feature-list"><li>Atalhos para WhatsApp Web, Cloud, Telegram e Gmail.</li><li>Conversas e ferramentas de atendimento no navegador.</li><li>Assistente Aito IA para apoiar conteúdo, fluxos e configurações.</li><li>Envie arquivos ou prints e use os atalhos do assistente para agilizar tarefas.</li></ul><small>Notificações dependem da permissão e compatibilidade do navegador. No iPhone, use o atalho instalado na tela inicial. O uso de IA depende da configuração e dos créditos do provedor.</small></div><div class="mobile-frames"><div><SolutionMediaFrame :src="offer.media?.mobilePush || solutionsMedia.mobile" phone title="Todos os canais no celular"/><p class="mobile-caption">Escolha o canal e continue de onde parou.</p></div><div><SolutionMediaFrame :src="offer.media?.mobileAssistant || solutionsMedia.assistant" phone title="Assistente Aito IA"/><p class="mobile-caption">Conteúdo, fluxos e configurações com apoio de IA.</p></div></div></section>

<section class="distribution-section"><span class="eyebrow">ESCOLHA ONDE SUA OPERAÇÃO RODA</span><h2>No seu computador ou no Render.</h2><p>A mesma licença do kit é aceita nas duas distribuições, respeitando as instalações autorizadas pelo plano.</p><div class="solution-pair"><article><q-icon name="mdi-monitor" size="36px"/><h3>Desktop</h3><p>Instalação guiada, banco e filas locais, sem Docker no modo padrão. Backup ZIP protegido por senha e acesso remoto de colaboradores pelo ngrok configurado.</p><small>O computador precisa ficar ligado. Licença e canais dependem de internet.</small></article><article><q-icon name="mdi-cloud-outline" size="36px"/><h3>Render / Blueprint</h3><p>Publique o sistema em infraestrutura de nuvem para atendimento e links públicos. Use o pacote de deploy e configure os provedores pelo painel.</p><small>Hospedagem, domínio e uso dos provedores são contratados separadamente.</small></article></div><p>Telegram e Gmail também fazem parte do kit: mensagens, templates e notificações em canais complementares.</p></section><section id="planos" class="solution-plans"><div class="section-heading"><span class="eyebrow">O PACOTE É COMPLETO. A ESCOLHA É SUA.</span><h2>Comece do jeito que faz sentido<br/><em>para sua empresa.</em></h2><p>API oficial e BotBuilder no mesmo ecossistema, com a autonomia do código-fonte ou acompanhamento da AitoSoftwares.</p></div><div class="plans-grid"><article class="plan-card plan-card--source"><span class="plan-chip">PARA QUEM QUER TER O CÓDIGO</span><h3>Comprar código-fonte</h3><p>Personalize, instale e evolua a sua própria operação.</p><div class="price"><s v-if="offer.originalPriceCents > offer.priceCents">{{ money(offer.originalPriceCents) }}</s><strong>{{ money(offer.priceCents) }}</strong><span>Pagamento único · licença para uma instalação</span></div><ul><li>AitoNotify + WhatsApp BotBuilder com API oficial e BotBuilder.</li><li>Código-fonte para personalizar e integrar.</li><li>Token de licença e download na sua conta.</li><li>Guias de instalação e configuração.</li></ul><q-btn unelevated no-caps color="teal-6" size="lg" label="Comprar código-fonte" icon="mdi-lock-outline" :disable="!offer.available" :loading="buying" @click="buy"/><small>Checkout InfinitePay. O download é liberado após a confirmação do pagamento.</small></article><article v-if="offer.monthlyEnabled" class="plan-card"><span class="plan-chip">PARA QUEM QUER COMEÇAR COM A EQUIPE</span><h3>{{ offer.monthlyTitle }}</h3><p>{{ offer.monthlyDescription || 'Avalie a implantação e a operação mensal com a AitoSoftwares.' }}</p><div class="price"><strong>{{ offer.monthlyPriceCents == null ? 'Vamos conversar' : money(offer.monthlyPriceCents) }}</strong><span>{{ offer.monthlyPriceCents == null ? 'Escopo e condições definidos com a equipe' : 'por mês · contratação com a equipe AITO' }}</span></div><ul><li>Definição dos canais e necessidades da operação.</li><li>Implantação e personalização conforme a proposta.</li><li>Apoio para configurar fluxos e modelos.</li><li>Infraestrutura e suporte definidos na contratação.</li></ul><q-btn outline no-caps color="teal-2" size="lg" label="Quero usar mensal" icon="mdi-whatsapp" :href="monthlyUrl" target="_blank" rel="noopener noreferrer"/><small>A conversa começa no WhatsApp da AitoSoftwares. A equipe confirma disponibilidade, escopo e condições.</small></article></div><p class="plans-footnote">Hospedagem, serviços de IA e eventuais cobranças da Meta são considerados à parte, conforme o plano e a configuração contratados.</p></section>
<section id="instalacao" class="guide"><span class="eyebrow">DA COMPRA À PRIMEIRA OPERAÇÃO</span><h2>Seu próximo passo já está desenhado.</h2><div class="steps"><article><b>01</b><h3>Escolha como começar</h3><p>Compre o código pelo checkout ou converse com a equipe sobre a versão mensal.</p></article><article><b>02</b><h3>Receba o acesso certo</h3><p>Na compra do código, sua conta recebe o ZIP e o token após a confirmação. No mensal, a equipe combina a implantação.</p></article><article><b>03</b><h3>Conecte, personalize, opere</h3><p>Configure os canais, prepare os templates e publique os fluxos adequados à sua operação.</p></article></div><details><summary>O pacote inclui as duas soluções de WhatsApp?</summary><p>Sim. AitoNotify + WhatsApp BotBuilder reúne o módulo para a API oficial da Meta e o BotBuilder com sessão WhatsApp Web. As conexões usam números independentes, com gestão integrada de contatos e permissões.</p></details><details><summary>Minha equipe pode acessar o mesmo WhatsApp com logins diferentes?</summary><p>Sim. No WhatsApp Web do kit AitoNotify + WhatsApp BotBuilder, cada colaborador pode ter seu próprio login e identificação nas respostas. A sessão é conectada uma vez por QR Code no servidor, e os atendentes acessam o painel pelo navegador. Amplie sua equipe dimensionando os acessos simultâneos conforme a infraestrutura e o plano da sua instalação.</p></details><details><summary>O disparo pela API oficial elimina o risco de bloqueio?</summary><p>A API oficial é o caminho para uma operação profissional com mais segurança. A AITO desenvolve a integração com base na documentação oficial da Meta, usando a Cloud API, modelos aprovados e contatos autorizados. Os envios utilizam a infraestrutura oficial e continuam sujeitos à capacidade e aos limites da sua conta. Com conteúdo adequado, consentimento e acompanhamento da qualidade, sua empresa tem uma base sólida para crescer com menor risco. Conteúdos indevidos, reclamações, falta de autorização e descumprimento das políticas podem gerar restrições; a decisão final permanece com a Meta.</p></details><details><summary>O que preciso para instalar o código?</summary><p>Uma licença ativa, ambiente compatível com Docker, banco de dados e os provedores que pretende usar. A API oficial exige sua conta e configuração na Meta. A IA usa sua chave e créditos. O guia acompanha o código.</p></details><details><summary>Posso mudar o logo, cores e telas?</summary><p>O painel permite personalizar a identidade visual. Com o código-fonte, você também pode desenvolver ajustes de interface e integrações conforme a necessidade.</p></details></section>
<footer>Kit AitoNotify + WhatsApp BotBuilder · AitoSoftwares <router-link to="/app?tab=products">Já comprei: acessar meus produtos →</router-link></footer>
